import json,pathlib
p=pathlib.Path(__file__).resolve().parent
d=json.loads((p/'data.json').read_text())
windows=d['selected_windows']
html='''<!doctype html><meta charset="utf-8"><title>TPS 趋势 · 真实数据方案对比</title>
<style>*{box-sizing:border-box}body{margin:0;background:#0d1117;color:#edf1f8;font:14px -apple-system,BlinkMacSystemFont,sans-serif}main{max-width:1220px;margin:auto;padding:30px}h1{font-size:26px;margin:0 0 8px}p{line-height:1.7;color:#bac5d4;margin:6px 0}header{margin-bottom:22px}.badge{color:#f38a51;background:#f38a5115;padding:5px 10px;border-radius:6px;font-size:12px}button,select{background:#202833;color:#edf1f8;border:1px solid #3a485b;border-radius:7px;padding:9px 12px;font:inherit}label{margin-left:14px}section{background:#151c25;border:1px solid #2c3747;border-radius:13px;margin:16px 0;padding:18px}.row{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card{background:#121923;border:1px solid #2a3545;border-radius:10px;padding:16px}h2{font-size:17px;margin:0 0 5px}.sub{font-size:12px;color:#9aaabd;min-height:38px}svg{width:100%;height:auto;overflow:visible}.metrics{display:flex;gap:42px;margin:20px 0}strong{font-size:26px;display:block;margin-bottom:4px}.hint{font-size:12px;color:#96a6bb}.foot{color:#b0bbcb;font-size:13px;line-height:1.7}#tooltip{position:fixed;pointer-events:none;display:none;padding:12px;background:#253246;border:1px solid #556984;border-radius:7px;z-index:9;white-space:pre;line-height:1.6}.legend{color:#f0793d;font-weight:600}input{accent-color:#ec7440}#series{padding-top:10px} .note{border-left:3px solid #ed804e;padding:5px 12px;margin-top:12px}</style>
<main><header><span class="badge">仅方案预览 · 本机真实数据 · 正式应用未改</span><h1 style="margin-top:14px">让阶段变化清楚，保留原始读数</h1><p>同一模型、同一时间段、同一 Y 轴比较。现版已经按 5 分钟加权，问题不是缺少分桶。</p></header>
<select id="window"></select><label>EMA 平滑 <select id="half"><option value="5">适中 · 半衰期 5 分钟</option><option value="10">较强 · 半衰期 10 分钟</option></select></label><label><input id="raw" type="checkbox" checked>保留原始桶</label>
<section><div id="meta"></div><div class="metrics" id="metrics"></div><div class="row"><div class="card"><h2>A · 原始折线（重绘）</h2><div class="sub">5 分钟 Σtoken ÷ Σ正文耗时<br>桶与桶直接连接</div><div id="a"></div></div><div class="card" style="border-color:#b8693e"><h2>B · EMA 趋势（建议先试）</h2><div class="sub">只使用当前与过去的桶<br>原始数据淡化，趋势线突出</div><div id="b"></div></div><div class="card"><h2>C · 最近 3 桶中位数</h2><div class="sub">抑制孤立尖峰更强<br>可能呈阶梯、丢掉短阶段</div><div id="c"></div></div></div><div class="note">图中为桶均速与平滑趋势，不是瞬时流式速度。平滑仅改变展示，不用于 Token 账本、计费或排行榜上报。</div></section>
<section><h2>近期真实样本：缺口和孤立读数仍然可见</h2><p>6.1 Sol · 最近 24 小时 · 缺失桶断线，不补零、不跨空白续画；不把一个孤立点解释为趋势。</p><div id="recent"></div></section>
<section class="foot"><b>拟定规则</b><p>5 分钟加权原桶保留；默认单模型，原点半透明；EMA 半衰期 5 分钟，提供“原始 / 适中 / 较强”。阶段前后数字直接用原始桶加权，不拿平滑值算平均。Y 轴沿用自适应但固定本次查看范围，始终显示刻度。</p><p>5 分钟 EMA 对真实阶跃：第一桶响应 50%，两桶 75%，三桶 87.5%；更平滑就必然更滞后。最近 3 桶中位数需要两桶确认，10 分钟短阶段可能被削弱。</p><p>自动“变点 / 额度重置”标注先不加。当前样本只能说明速度变化，不能证明服务器拥堵或额度重置的因果。可先展示“前 15 分钟 vs 后 15 分钟”的可复算数值。</p><p>性能：读取现有 SQLite 五分钟汇总，预计算一次 O(n)，数据/模型/范围改变时重算；滚动与悬停不读库、不重做平滑，无额外定时器。7 天与 30 天沿用现有 30 分钟 / 2 小时底桶，平滑说明随范围变化。</p></section><div class="hint">数值快照：2026-10-25 13:56（北京时间）；只读 SQLite speed_5m。3 个窗口均为真实历史，第一段为专门挑出的阶段变化示例，并非全体性能保证。</div></main><div id="tooltip"></div>
<script>const windows=WINDOWS, latest=LATEST;
const names=['10/22 00:15–01:25 · 约 50→40 示例','10/22 17:10–18:15 · 较弱下降','10/22 19:05–20:10 · 稀疏且波动'];
const select=document.querySelector('#window');windows.forEach((w,i)=>select.add(new Option(names[i],i)));
function rate(r){return r.tokens_per_second}function weighted(a){return a.reduce((s,r)=>s+r.output_tokens,0)/a.reduce((s,r)=>s+r.duration_seconds,0)}
function date(t){return new Date((t+8*3600)*1000).toISOString().slice(11,16)}
function series(rows,mode){let out=[],prev=null,history=[];for(const r of rows){let gap=prev&&r.bucket_start_epoch_utc-prev.bucket_start_epoch_utc>300;if(gap){history=[];}history.push(rate(r));let y=rate(r);if(mode==='ema'&&prev&&!gap){let a=1-Math.pow(2,-5/Number(document.querySelector('#half').value));y=out.at(-1)+(y-out.at(-1))*a;}if(mode==='median'&&history.length>=3){y=history.slice(-3).sort((a,b)=>a-b)[1]}out.push(y);prev=r}return out}
function chart(rows,mode,width=330,height=255,range=null){const ys=rows.map(rate), vals=series(rows,mode),l=39,r=12,top=20,bottom=35;const lo=range?.[0]??Math.max(0,Math.floor((Math.min(...ys)-5)/5)*5),hi=range?.[1]??Math.ceil((Math.max(...ys)+5)/5)*5;const t0=rows[0].bucket_start_epoch_utc,t1=rows.at(-1).bucket_start_epoch_utc;const x=t=>l+(t-t0)/(t1-t0||300)*(width-l-r),y=v=>top+(hi-v)/(hi-lo)*(height-top-bottom);let s=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${mode} TPS 趋势"><text x="1" y="10" fill="#a8b7c8" font-size="10">tok/s</text>`;for(let i=0;i<=4;i++){const v=lo+(hi-lo)*i/4;s+=`<line x1="${l}" y1="${y(v)}" x2="${width-r}" y2="${y(v)}" stroke="#283447"/><text x="${l-8}" y="${y(v)+4}" text-anchor="end" fill="#a8b7c8" font-size="11">${v.toFixed(0)}</text>`}for(let i=0;i<4;i++){let t=t0+(t1-t0)*i/3;s+=`<text x="${x(t)}" y="${height-10}" text-anchor="middle" fill="#a8b7c8" font-size="10">${date(t)}</text>`}
function line(v,color,opacity,stroke){let d='';rows.forEach((p,i)=>{const gap=i&&p.bucket_start_epoch_utc-rows[i-1].bucket_start_epoch_utc>300;d+=`${i&&!gap?'L':'M'}${x(p.bucket_start_epoch_utc).toFixed(2)},${y(v[i]).toFixed(2)} `});return `<path d="${d}" fill="none" stroke="${color}" opacity="${opacity}" stroke-width="${stroke}" stroke-linejoin="round"/>`}
const show=mode==='raw'||document.querySelector('#raw').checked;if(show)s+=line(ys,'#f07e48',mode==='raw'?1:.25,mode==='raw'?1.6:1);if(mode!=='raw')s+=line(vals,'#f48650',1,2.8);rows.forEach((p,i)=>{s+=`<circle cx="${x(p.bucket_start_epoch_utc)}" cy="${y(show?ys[i]:vals[i])}" r="${p.sample_count<3?3:2.5}" fill="${p.sample_count<3?'#141c27':'#f48650'}" stroke="#f48650" opacity="${mode==='raw'?1:.5}"><title>${date(p.bucket_start_epoch_utc)} · ${rate(p).toFixed(2)} TPS\n${p.sample_count} 段 · ${p.output_tokens} token / ${p.duration_seconds.toFixed(3)} 秒\n趋势 ${vals[i].toFixed(2)} TPS${p.sample_count<3?' · 样本偏少':''}</title></circle>`});return s+'</svg>'}
function render(){let w=windows[Number(select.value)],rows=w.records,first=weighted(rows.slice(0,3)),last=weighted(rows.slice(-3));document.querySelector('#meta').innerHTML='<b class="legend">gpt-6.1-sol</b> · '+rows.length+' 个连续五分钟桶 · '+w.aggregate.sample_count+' 段正文 · 空心点为少于 3 段的桶';document.querySelector('#metrics').innerHTML=`<div><strong>${first.toFixed(1)} TPS</strong>前 15 分钟 · 原始加权</div><div><strong>${last.toFixed(1)} TPS</strong>后 15 分钟 · 原始加权</div><div><strong style="color:#ed945e">${((last/first-1)*100).toFixed(1)}%</strong>阶段差值 · 不等同重置因果</div>`;['raw','ema','median'].forEach((m,i)=>document.querySelector('#'+['a','b','c'][i]).innerHTML=chart(rows,m));let recent=latest.filter(r=>r.model==='gpt-6.1-sol');document.querySelector('#recent').innerHTML=chart(recent,'ema',1120,230)}
select.onchange=render;document.querySelector('#half').onchange=render;document.querySelector('#raw').onchange=render;render();</script>'''
latest=d['latest_24h']
print(type(latest),list(latest) if isinstance(latest,dict) else len(latest))
if isinstance(latest,dict):latest=latest['records']
html=html.replace('WINDOWS',json.dumps(windows)).replace('LATEST',json.dumps(latest))
(p/'index.html').write_text(html)
